import{_ as r,o as d,c as o,ag as a}from"./chunks/framework.D2veAa-g.js";const c=JSON.parse('{"title":"架构师-备考 综合知识-软件工程-软件测试","description":"","frontmatter":{"title":"架构师-备考 综合知识-软件工程-软件测试"},"headers":[],"relativePath":"综合知识/软件工程/软件测试.md","filePath":"综合知识/软件工程/软件测试.md","lastUpdated":null}'),e={name:"综合知识/软件工程/软件测试.md"};function n(l,t,s,h,g,i){return d(),o("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 测试原则（尽早测试/非开发者测试/正向+反向用例）</li><li>[x] 静态测试 vs 动态测试</li><li>[x] 黑盒测试 vs 白盒测试</li><li>[x] 测试阶段（单元/集成/确认/系统/配置项/回归）</li><li>[x] Alpha/Beta/验收测试区别</li><li>[x] 黑盒测试用例设计（等价类/边界值/错误推测/因果图）</li><li>[x] 白盒测试用例设计（语句/判定/条件/判定条件组合/路径覆盖）</li><li>[x] 调试方法（蛮力法/回溯法/原因排除法）</li><li>[x] McCabe 环路复杂度计算（m-n+2）</li><li>[x] 软件度量（外部属性/内部属性）</li><li>[x] 灰盒测试</li><li>[x] 判定表测试（多逻辑条件组合）</li><li>[x] 测试脚本类型（线性/结构化/数据驱动/共享）</li><li>[x] 静态分析类型（控制流/数据流/接口/表达式分析）</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、测试原则-★" tabindex="-1">一、测试原则 ★ <a class="header-anchor" href="#一、测试原则-★" aria-label="Permalink to &quot;一、测试原则 ★&quot;">​</a></h3><blockquote><p>测试是为了<strong>发现错误</strong>而执行程序的过程，成功的测试是发现了至今尚未发现的错误的测试。</p></blockquote><p><strong>核心原则：</strong></p><ul><li>应尽早并不断进行测试</li><li>测试工作应避免由原开发软件的人或小组承担</li><li>设计测试方案时，要确定输入数据和<strong>预期的输出结果</strong></li><li>既包含有效合理的用例，也包含不合理失效的用例</li><li>检验程序是否做了该做的事，且是否做了不该做的事</li><li>严格按照测试计划进行，妥善保存测试计划和测试用例</li><li>测试用例可以重复使用或追加测试</li></ul><hr><h3 id="二、测试方法分类-★" tabindex="-1">二、测试方法分类 ★ <a class="header-anchor" href="#二、测试方法分类-★" aria-label="Permalink to &quot;二、测试方法分类 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>对比维度</th><th>静态测试</th><th>动态测试</th></tr></thead><tbody><tr><td><strong>方式</strong></td><td>被测程序<strong>不在机器上运行</strong></td><td><strong>实际运行程序</strong></td></tr><tr><td><strong>手段</strong></td><td>人工检测 + 计算机辅助静态分析</td><td>白盒测试 + 黑盒测试</td></tr><tr><td><strong>文档测试</strong></td><td>以<strong>检查单</strong>形式进行</td><td>—</td></tr><tr><td><strong>代码测试</strong></td><td>桌前检查、代码审查、代码走查</td><td>—</td></tr><tr><td><strong>效果</strong></td><td>有效发现 30%-70% 逻辑设计和编码错误</td><td>—</td></tr></tbody></table><p><strong>黑盒测试 vs 白盒测试：</strong></p><table tabindex="0"><thead><tr><th>对比</th><th>黑盒测试</th><th>白盒测试</th></tr></thead><tbody><tr><td>别名</td><td><strong>功能性测试</strong></td><td><strong>结构性测试</strong></td></tr><tr><td>特点</td><td>不了解代码结构</td><td>明确代码流程</td></tr><tr><td>依据</td><td>根据功能设计用例</td><td>根据代码逻辑设计用例</td></tr><tr><td>目标</td><td>测试软件功能</td><td>进行用例覆盖</td></tr></tbody></table><hr><h3 id="三、测试阶段-★" tabindex="-1">三、测试阶段 ★ <a class="header-anchor" href="#三、测试阶段-★" aria-label="Permalink to &quot;三、测试阶段 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>阶段</th><th>测试对象</th><th>测试依据</th><th>目的</th></tr></thead><tbody><tr><td><strong>单元测试</strong></td><td>可独立编译的模块/类</td><td><strong>软件详细设计说明书</strong></td><td>模块功能正确性</td></tr><tr><td><strong>集成测试</strong></td><td>模块间接口</td><td><strong>软件概要设计文档</strong></td><td>检查模块间接口关系</td></tr><tr><td><strong>确认测试</strong></td><td>完整软件</td><td>SRS</td><td>验证功能/性能与用户需求一致</td></tr><tr><td><strong>系统测试</strong></td><td>完整的集成计算机系统</td><td>用户需求/开发合同</td><td>验证与系统正确连接，满足设计要求</td></tr><tr><td><strong>配置项测试</strong></td><td>软件配置项</td><td>SRS</td><td>检验与 SRS 一致性</td></tr><tr><td><strong>回归测试</strong></td><td>变更后的软件</td><td>—</td><td>验证变更正确性+不影响原有功能</td></tr></tbody></table><p><strong>确认测试按用户参与程度：</strong></p><table tabindex="0"><thead><tr><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><strong>内部确认测试</strong></td><td>开发组织内部按 SRS 测试</td></tr><tr><td><strong>Alpha 测试</strong></td><td>用户<strong>在开发环境</strong>下测试</td></tr><tr><td><strong>Beta 测试</strong></td><td>用户<strong>在实际使用环境</strong>下测试，通过后交付</td></tr><tr><td><strong>验收测试</strong></td><td>交付前<strong>以用户为主</strong>的测试，依据 SRS/合同</td></tr></tbody></table><blockquote><p>系统测试最重要的工作是<strong>功能测试与性能测试</strong>。功能测试主要用黑盒测试，性能测试指标：响应时间、吞吐量、并发用户数、资源利用率。</p></blockquote><hr><h3 id="四、测试用例设计-★" tabindex="-1">四、测试用例设计 ★ <a class="header-anchor" href="#四、测试用例设计-★" aria-label="Permalink to &quot;四、测试用例设计 ★&quot;">​</a></h3><h4 id="黑盒测试用例" tabindex="-1">黑盒测试用例 <a class="header-anchor" href="#黑盒测试用例" aria-label="Permalink to &quot;黑盒测试用例&quot;">​</a></h4><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><strong>等价类划分</strong></td><td>按特性归类，每类选取一个代表。有效等价类：尽可能多覆盖；无效等价类：<strong>每次仅覆盖一个</strong></td></tr><tr><td><strong>边界值划分</strong></td><td>取范围两端值及范围外相邻值（如 0-150 → 0, 150, -1, 151）</td></tr><tr><td><strong>错误推测</strong></td><td>凭经验推测可能出问题的地方</td></tr><tr><td><strong>因果图</strong></td><td>由结果反推原因</td></tr></tbody></table><h4 id="白盒测试用例-覆盖级别从低→高" tabindex="-1">白盒测试用例（覆盖级别从低→高） <a class="header-anchor" href="#白盒测试用例-覆盖级别从低→高" aria-label="Permalink to &quot;白盒测试用例（覆盖级别从低→高）&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:center;">级别</th><th>说明</th></tr></thead><tbody><tr><td style="text-align:center;"><strong>语句覆盖 SC</strong></td><td>所有语句至少执行一遍，<strong>覆盖层级最低</strong></td></tr><tr><td style="text-align:center;"><strong>判定覆盖 DC</strong></td><td>所有判断的<strong>真假分支</strong>都覆盖一次</td></tr><tr><td style="text-align:center;"><strong>条件覆盖 CC</strong></td><td>每个判断条件内的<strong>每个独立条件</strong>都执行一遍真和假</td></tr><tr><td style="text-align:center;"><strong>判定条件组合覆盖 CDC</strong></td><td>同时满足判定覆盖和条件覆盖</td></tr><tr><td style="text-align:center;"><strong>路径覆盖</strong></td><td>所有可行路径都覆盖，<strong>覆盖层级最高</strong></td></tr></tbody></table><blockquote><p>覆盖层级口诀：<strong>语句&lt;判定&lt;条件&lt;判定条件组合&lt;路径</strong>。</p></blockquote><hr><h3 id="五、调试" tabindex="-1">五、调试 <a class="header-anchor" href="#五、调试" aria-label="Permalink to &quot;五、调试&quot;">​</a></h3><blockquote><p>测试是发现错误，调试是<strong>找出错误的代码和原因</strong>。</p></blockquote><p><strong>调试方法：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>说明</th></tr></thead><tbody><tr><td><strong>蛮力法</strong></td><td>全面排查</td></tr><tr><td><strong>回溯法</strong></td><td>从出错位置<strong>往回找</strong></td></tr><tr><td><strong>原因排除法</strong></td><td>找出所有可能原因逐一排除，含演绎法、归纳法、二分法</td></tr></tbody></table><blockquote><p>调试后需要进行<strong>回归测试</strong>。</p></blockquote><hr><h3 id="六、mccabe-环路复杂度" tabindex="-1">六、McCabe 环路复杂度 <a class="header-anchor" href="#六、mccabe-环路复杂度" aria-label="Permalink to &quot;六、McCabe 环路复杂度&quot;">​</a></h3><blockquote><p><strong>环路复杂度 = m - n + 2</strong>，其中 m = 有向边数（分支连线），n = 节点数（语句框）。</p></blockquote><hr><h3 id="七、补充考点" tabindex="-1">七、补充考点 <a class="header-anchor" href="#七、补充考点" aria-label="Permalink to &quot;七、补充考点&quot;">​</a></h3><h4 id="灰盒测试-★" tabindex="-1">灰盒测试 ★ <a class="header-anchor" href="#灰盒测试-★" aria-label="Permalink to &quot;灰盒测试 ★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：灰盒测试<strong>既关注内部程序逻辑又考虑外部功能</strong>，但不像白盒测试那样详细和完整。</p></blockquote><h4 id="判定表测试-★" tabindex="-1">判定表测试 ★ <a class="header-anchor" href="#判定表测试-★" aria-label="Permalink to &quot;判定表测试 ★&quot;">​</a></h4><blockquote><p>🎯 一句话结论：<strong>判定表</strong>最适合描述在多个逻辑条件取值组合构成的复杂情况下分别执行哪些不同动作。</p></blockquote><h4 id="自动化测试脚本类型-★" tabindex="-1">自动化测试脚本类型 ★ <a class="header-anchor" href="#自动化测试脚本类型-★" aria-label="Permalink to &quot;自动化测试脚本类型 ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">脚本类型</th><th>特点</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>线性脚本</strong></td><td><strong>录制手工测试</strong>时得到的脚本，无判断和循环</td></tr><tr><td style="text-align:left;"><strong>结构化脚本</strong></td><td>包含控制结构（判断、循环）</td></tr><tr><td style="text-align:left;"><strong>数据驱动脚本</strong></td><td>测试输入存储在<strong>独立的数据文件</strong>中，不在脚本中</td></tr><tr><td style="text-align:left;"><strong>共享脚本</strong></td><td>可被多个测试用例复用的脚本</td></tr></tbody></table><h4 id="静态分析类型-★" tabindex="-1">静态分析类型 ★ <a class="header-anchor" href="#静态分析类型-★" aria-label="Permalink to &quot;静态分析类型 ★&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">分析类型</th><th>检测内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>控制流分析</strong></td><td>程序执行路径，如死代码、无限循环</td></tr><tr><td style="text-align:left;"><strong>数据流分析</strong></td><td>引用未定义的变量、未使用的变量赋值等</td></tr><tr><td style="text-align:left;"><strong>接口分析</strong></td><td>模块接口一致性，参数类型/个数匹配</td></tr><tr><td style="text-align:left;"><strong>表达式分析</strong></td><td>表达式正确性、优先级等</td></tr></tbody></table><blockquote><p>⚠️ 易错：引用未定义变量属于<strong>数据流分析</strong>，不是控制流分析。</p></blockquote><h4 id="系统测试特点" tabindex="-1">系统测试特点 <a class="header-anchor" href="#系统测试特点" aria-label="Permalink to &quot;系统测试特点&quot;">​</a></h4><p>系统测试主要采用<strong>黑盒测试</strong>方法，检查系统是否符合软件需求（不是白盒也不是内部逻辑验证）。</p><h4 id="测试标准流程" tabindex="-1">测试标准流程 <a class="header-anchor" href="#测试标准流程" aria-label="Permalink to &quot;测试标准流程&quot;">​</a></h4><p><strong>单元测试 → 集成测试 → 系统测试</strong>（不可颠倒）</p><h4 id="web-专项测试" tabindex="-1">Web 专项测试 <a class="header-anchor" href="#web-专项测试" aria-label="Permalink to &quot;Web 专项测试&quot;">​</a></h4><ul><li><strong>链接测试</strong>：验证所有超链接是否有效、指向正确页面</li><li>压力测试前应先进行<strong>基准测试</strong>验证正常负载下的资源占用</li></ul><hr><h3 id="八、软件度量" tabindex="-1">八、软件度量 <a class="header-anchor" href="#八、软件度量" aria-label="Permalink to &quot;八、软件度量&quot;">​</a></h3><table tabindex="0"><thead><tr><th>属性类型</th><th>说明</th><th>特点</th></tr></thead><tbody><tr><td><strong>外部属性</strong></td><td>面向管理者和用户，如性能指标</td><td>可直接测量</td></tr><tr><td><strong>内部属性</strong></td><td>软件产品本身的属性，如可靠性</td><td>只能间接测量</td></tr></tbody></table>',54)])])}const u=r(e,[["render",n]]);export{c as __pageData,u as default};
